#include <iostream>
#include <unordered_map>
int main() {
    std::unordered_map<int, int> counts;
    for (int x : {4, 4, 7}) ++counts[x];
    std::cout << counts[4] << '\n';
}

#include <iostream>
#include <unordered_set>
