#include <iostream>
#include <stack>
int main() {
    std::stack<int> pending;
    pending.push(3);
    pending.push(8);
    int value = pending.top();
    pending.pop();
    std::cout << value << ' ' << pending.top() << '\n';
}

#include <iostream>
#include <queue>
int main() {
    std::queue<int> pending;
    pending.push(3);
    pending.push(8);
    std::cout << pending.front() << ' ';
    pending.pop();
    std::cout << pending.front() << '\n';
}

#include <iostream>
#include <queue>
#include <vector>
#include <functional>
int main() {
    std::priority_queue<int, std::vector<int>, std::greater<int>> q;
    q.push(8); q.push(3); q.push(5);
    std::cout << q.top() << '\n';
}

#include <algorithm>
#include <iostream>
#include <vector>
int main() {
    std::vector<int> v{7, 2, 5};
    std::sort(v.begin(), v.end());
    auto it = std::lower_bound(v.begin(), v.end(), 4);
    if (it != v.end()) std::cout << *it << '\n';
}

